//! Native menu input shares the window's ordered input stream. A raw-input hook
//! alone is too late: it would append a command after later keyboard events.
use egui::{Context, Event, Id, ViewportId};
use std::{
    collections::VecDeque,
    sync::{Arc, Mutex, Weak},
};

/// Input generated by an application's native menu callback.
#[derive(Clone, Debug)]
pub enum NativeInput {
    /// A semantic command or a normal editing event.
    Event(Event),
    /// Read the window backend's clipboard before the next window input event.
    Paste,
}

struct Pending {
    queue: Mutex<VecDeque<(u64, NativeInput)>>,
    diagnostic: Option<crate::diagnostics::Bridge>,
    viewport: ViewportId,
}

fn key(viewport: ViewportId) -> Id {
    Id::new(("wireframe-native-input", viewport))
}

fn pending(ctx: &Context, viewport: ViewportId) -> Option<Arc<Pending>> {
    ctx.data(|data| data.get_temp::<Weak<Pending>>(key(viewport)))?
        .upgrade()
}

/// Whether the viewport currently has a live window input backend.
pub fn is_available(ctx: &Context, viewport: ViewportId) -> bool {
    pending(ctx, viewport).is_some()
}

/// Queue input from the UI thread. Returns false after the window is destroyed,
/// or when no native window backend is attached (for example in headless tests).
pub fn send(ctx: &Context, viewport: ViewportId, input: NativeInput) -> bool {
    let Some(pending) = pending(ctx, viewport) else {
        if let Some(bridge) = crate::diagnostics::Bridge::for_context(ctx, viewport) {
            let seq = bridge.next_event();
            bridge.record(crate::diagnostics::Receipt {
                seq,
                ..crate::diagnostics::Receipt::new("enqueue_failed", viewport)
            });
        }
        return false;
    };
    let seq = pending.diagnostic.as_ref().map_or(0, |b| b.next_event());
    if let Some(bridge) = &pending.diagnostic {
        match &input {
            NativeInput::Event(event) => bridge.input("native_enqueued", viewport, seq, event),
            NativeInput::Paste => bridge.record(crate::diagnostics::Receipt {
                seq,
                ..crate::diagnostics::Receipt::new("native_paste_enqueued", viewport)
            }),
        }
    }
    pending
        .queue
        .lock()
        .unwrap_or_else(|e| e.into_inner())
        .push_back((seq, input));
    ctx.request_repaint_of(viewport);
    true
}

pub(crate) struct Queue(Arc<Pending>);

impl Queue {
    #[cfg(test)]
    pub(crate) fn register(ctx: &Context, viewport: ViewportId) -> Self {
        Self::register_with_diagnostics(ctx, viewport, None)
    }
    pub(crate) fn register_with_diagnostics(
        ctx: &Context,
        viewport: ViewportId,
        diagnostic: Option<crate::diagnostics::Bridge>,
    ) -> Self {
        if let Some(bridge) = &diagnostic {
            bridge.attach(ctx, viewport);
        }
        let queue = Self(Arc::new(Pending {
            queue: Mutex::new(VecDeque::new()),
            diagnostic,
            viewport,
        }));
        ctx.data_mut(|data| data.insert_temp(key(viewport), Arc::downgrade(&queue.0)));
        queue
    }

    pub(crate) fn drain_into(
        &self,
        events: &mut Vec<Event>,
        mut paste: impl FnMut() -> Option<String>,
    ) -> u64 {
        // Release the queue lock before accessing platform clipboard APIs.
        let pending = std::mem::take(&mut *self.0.queue.lock().unwrap_or_else(|e| e.into_inner()));
        let mut last = 0;
        for (seq, input) in pending {
            last = last.max(seq);
            if let Some(bridge) = &self.0.diagnostic {
                bridge.record(crate::diagnostics::Receipt {
                    seq,
                    ..crate::diagnostics::Receipt::new("native_drained", self.0.viewport)
                });
            }
            match input {
                NativeInput::Event(event) => {
                    if let Some(bridge) = &self.0.diagnostic {
                        bridge.input("mapped", self.0.viewport, seq, &event);
                    }
                    events.push(event);
                }
                NativeInput::Paste => {
                    if let Some(text) = paste().filter(|s| !s.is_empty()) {
                        let event = Event::Paste(text.replace("\r\n", "\n"));
                        if let Some(bridge) = &self.0.diagnostic {
                            bridge.input("mapped", self.0.viewport, seq, &event);
                        }
                        events.push(event);
                    }
                }
            }
        }
        last
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn menu_input_precedes_later_window_input_and_preserves_paste_save_order() {
        let ctx = Context::default();
        let queue = Queue::register(&ctx, ViewportId::ROOT);
        let mut events = vec![Event::Text("before".into())];
        assert!(send(&ctx, ViewportId::ROOT, NativeInput::Paste));
        assert!(send(
            &ctx,
            ViewportId::ROOT,
            NativeInput::Event(Event::AppCommand(7))
        ));
        queue.drain_into(&mut events, || Some("paste\r\n".into()));
        events.push(Event::Text("after".into()));
        queue.drain_into(&mut events, || panic!("clipboard read twice"));
        assert_eq!(
            events,
            vec![
                Event::Text("before".into()),
                Event::Paste("paste\n".into()),
                Event::AppCommand(7),
                Event::Text("after".into())
            ]
        );
    }

    #[test]
    fn commands_do_not_leak_between_windows_or_outlive_the_backend() {
        let ctx = Context::default();
        let other = ViewportId::from_hash_of("other");
        assert!(!is_available(&ctx, ViewportId::ROOT));
        let first = Queue::register(&ctx, ViewportId::ROOT);
        let second = Queue::register(&ctx, other);
        send(&ctx, other, NativeInput::Event(Event::AppCommand(1)));
        let mut events = vec![];
        first.drain_into(&mut events, || None);
        assert!(events.is_empty());
        second.drain_into(&mut events, || None);
        assert_eq!(events, vec![Event::AppCommand(1)]);
        drop(second);
        assert!(!send(&ctx, other, NativeInput::Paste));
        assert!(is_available(&ctx, ViewportId::ROOT));
    }
}
